// 관광지 상세 페이지 "길찾기" 이동수단 아이콘 (자동차/대중교통/도보/자전거).
// 원본은 사용자가 제공한 PNG(투명 배경 + 흰색 아이콘)를 base64로 인코딩해
// 여기에 직접 넣어둔 것입니다 — 별도 이미지 파일 없이 이 코드 파일 하나로 끝납니다.
// 그림 영역만 잘라 정사각형 캔버스 중앙에 재배치해서, 원형 배경 안에서
// 아이콘이 한쪽으로 치우쳐 보이지 않게(정중앙 정렬) 처리했습니다. 경계
// 계산 시 알파값이 낮은 노이즈 픽셀(예: 자동차 아이콘 왼쪽 끝 점 하나)은
// 무시하도록 임계값을 둬서, 실제 그림 밖의 노이즈에 좌우되지 않게 했습니다.

export const CAR_ICON_BASE64 = "data:image/png;base64,";

export const PUBLIC_TRANSIT_ICON_BASE64 = "data:image/png;base64,";

export const FOOT_ICON_BASE64 = "data:image/png;base64,";

